SOURCE_INPUTS={'vehicle': {'bytes': 18192, 'sha256': '2efd4c2f5b2b99188e22609d77a96c3c7632e768ce5fdc79043bc586f2697fe5', 'compressed': ''}, 'picnic': {'bytes': 15676, 'sha256': '161d254d7fc04efb384deaccff50418475b99ea40d502a4f33684e5318552393', 'compressed': ''}, 'waste': {'bytes': 34761, 'sha256': '160478f28ae70731b2e006a00b006b5e0ef2b71375d1cf7418a0e15a374ad67c', 'compressed': ''}}
